    toothbrush_patches = image_patch.find("toothbrush")
    if not toothbrush_patches: return image_patch

    green_toothbrush = [t for t in toothbrush_patches if t.verify_property("toothbrush", "green")]
    orange_toothbrush = [t for t in toothbrush_patches if t.verify_property("toothbrush", "orange")]

    if green_toothbrush and orange_toothbrush:
        return green_toothbrush[0] if depth_order(green_toothbrush)[0].compute_depth() < depth_order(orange_toothbrush)[0].compute_depth() else orange_toothbrush[0]
    elif green_toothbrush:
        return green_toothbrush[0]
    elif orange_toothbrush:
        return orange_toothbrush[0]
    else:
        return toothbrush_patches[0]

